INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75271, 'spa', 'Pastorear/apacentar (literal)', 'Pastorear/apacentar (literal). Ganadería literal: arrear, cuidar o apacentar ovejas y ganado. En Lucas 17:7 un siervo regresa de ''apacentar'' en el campo, y la pregunta retórica de Pablo en 1 Corintios 9:7 apela al derecho común del pastor de beber la leche del rebaño. Judas 1:12 usa el participio de quienes ''se apacientan a sí mismos'', torciendo la imagen literal en reproche.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75276, 'spa', 'El que cuida, guía, alimenta y protege un rebaño -- usado tanto literalmente par', 'El que cuida, guía, alimenta y protege un rebaño -- usado tanto literalmente para quienes guardan ovejas como figuradamente para los líderes que velan por el pueblo de Dios. Los pastores de Belén en Lucas 2:8-20 son los primeros testigos de la encarnación, y su humilde condición resalta el favor divino hacia los sencillos. Jesús se llama a sí mismo ''el buen pastor'' que da su vida por sus ovejas (Jn 10:2, 11-12, 14, 16), y Efesios 4:11 incluye ''pastores y maestros'' entre los dones dados a la iglesia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75280, 'spa', 'Rebaño', 'Rebaño de ovejas o cabras, usado tanto literalmente para animales como metafóricamente para el pueblo de Dios bajo el cuidado de un pastor. El sentido literal aparece en Lc 2:8, donde pastores cuidan su rebaño la noche del nacimiento de Jesús, escena cargada de resonancia simbólica en la teología del «Cordero de Dios». Mt 26:31 cita Zacarías 13:7, aplicando la dispersión del rebaño al abandono de los discípulos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75281, 'spa', 'Rebañito', 'Rebaño o rebañito, originalmente de ovejas o cabras, pero en cada aparición neotestamentaria usado metafóricamente para la comunidad de creyentes bajo cuidado pastoral. La forma diminutiva (de ποίμνη) añade calidez e intimidad: el «rebañito» de Jesús en Lc 12:32 es deliberadamente pequeño y vulnerable, pero destinado al reino. En Hch 20:28-29, Pablo advierte a los ancianos de Éfeso que guarden el ποίμνιον de lobos rapaces.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75282, 'spa', 'cuál, qué (selección interrogativa)', 'cuál, qué (selección interrogativa)');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75283, 'spa', 'de qué clase, qué tipo de', 'de qué clase, qué tipo de');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75294, 'spa', 'Hacer guerra, pelear', 'Hacer guerra, pelear, combatir — denota conflicto armado o enfrentamiento hostil, desde la guerra cósmica apocalíptica hasta la contienda interpersonal. En Apocalipsis describe batallas celestiales: Miguel y sus ángeles «guerreando» contra el dragón (Apocalipsis 12:7), la aparentemente invencible capacidad bélica de la bestia (Apocalipsis 13:4), y Cristo amenazando con «guerrear» contra los infieles con la espada de su boca (Apocalipsis 2:16).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75300, 'spa', 'Conflicto armado entre fuerzas opuestas, que abarca enfrentamientos militares li', 'Conflicto armado entre fuerzas opuestas, que abarca enfrentamientos militares literales, batallas escatológicas y la guerra metafórica de las pasiones humanas. En el discurso apocalíptico sinóptico, Jesús predice ''guerras y rumores de guerras'' como señales que preceden al fin (Mt 24:6; Mr 13:7; Lc 21:9). Lucas 14:31 lo usa en sentido práctico para un rey que evalúa sus posibilidades militares. Santiago 4:1 rastrea los conflictos interpersonales hasta los deseos internos que combaten en los miembros. En Apocalipsis se eleva a guerra cósmica entre el cielo y las fuerzas del mal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75303, 'spa', 'ciudad, pueblo', 'Centro urbano habitado o pueblo, usado 165 veces tanto para ciudades con nombre (Jerusalén, Belén, Nazaret, Éfeso) como para referencias genéricas a poblaciones. Πόλις proporciona el armazón geográfico de los Evangelios y Hechos, desde la natividad en Belén (Mt 2:23) hasta los viajes misioneros de Pablo por las ciudades de Asia Menor, extendiéndose hasta la ''ciudad santa'' escatológica de Apocalipsis 21:2.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75311, 'spa', 'Ciudadanía celestial', 'La ciudadanía celestial que los creyentes poseen según Filipenses 3:20. Aunque viven como residentes en la tierra, los cristianos pertenecen a una comunidad política diferente. Esto resonaría poderosamente entre ciudadanos romanos que valoraban su ciudadanía, y más aún entre quienes carecían de tal estatus. Pablo afirma que nuestra verdadera ciudadanía y lealtad pertenecen al reino celestial.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75313, 'spa', 'Ciudadano', 'Ciudadano o conciudadano de una ciudad-estado, alguien que posee membresía reconocida en una comunidad política. En Lc 15:15 un ciudadano de aquella comarca contrata al hijo pródigo, y en Lc 19:14 los ciudadanos aborrecen al noble que parte; ambos usos parabólicos resaltan la pertenencia social. Pablo se identifica como ciudadano de Tarso (Hch 21:39), mientras que He 8:11 extiende el concepto al ámbito del nuevo pacto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75314, 'spa', 'Adverbio temporal que indica una ocurrencia repetida o frecuente', 'Adverbio temporal que indica una ocurrencia repetida o frecuente. En los Evangelios describe la violencia habitual de la aflicción demoníaca: un muchacho arrojado ''muchas veces'' al fuego y al agua (Mt 17:15; Mr 9:22) y un hombre atado ''muchas veces'' con cadenas (Mr 5:4). Juan 18:2 lo usa para las visitas regulares de Jesús a Getsemaní. Pablo cataloga sus repetidas dificultades apostólicas con πολλάκις -- peligros encontrados ''muchas veces'' en viajes, naufragios y persecuciones (2 Co 11:26-27).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75315, 'spa', 'Retribución multiplicada', 'La retribución multiplicada prometida en Lucas 18:30 a quienes sacrifican por el reino de Dios. Jesús asegura que las pérdidas son más que compensadas con ganancias abundantes: familia, comunidad, recursos, multiplicados muchas veces. Las traducciones multilingües subrayan la multiplicación (''many-times-more'', ''mucho-más''). No es simple reposición aritmética, sino recompensa divina generosa y sobreabundante.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75316, 'spa', 'Palabrería vana', 'La verborrea excesiva que Jesús condena en Mateo 6:7 como característica de la oración pagana. Los gentiles creían que serían escuchados por sus ''muchas palabras'', fórmulas largas y repetitivas diseñadas para manipular a la divinidad. Jesús contrasta esto con la oración sencilla y confiada a un Padre que ya conoce nuestras necesidades.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75317, 'spa', 'Revelación fragmentaria', 'La naturaleza parcial e incremental de la revelación veterotestamentaria descrita en Hebreos 1:1. Dios habló ''en muchas partes'' a través de diversos profetas durante siglos, construyendo su revelación pieza por pieza. Cada profeta aportó un fragmento hasta que la revelación alcanzó su plenitud en Cristo, la Palabra definitiva y completa del Padre.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75318, 'spa', 'Sabiduría multiforme', 'La sabiduría multifacética de Dios manifestada en Efesios 3:10 a través de la iglesia. Como un tapiz ricamente abigarrado o un mosaico de múltiples tonalidades, la sabiduría divina exhibe variedad y complejidad infinitas. La unidad diversa de la iglesia, donde judíos y gentiles son reconciliados, revela a los poderes celestiales la riqueza caleidoscópica del plan de Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75319, 'spa', 'muchos, numerosos', 'Muchos, numerosos — referido a un número grande de personas o cosas contables. El sentido dominante con 202 apariciones: ''vendrán muchos del oriente y del occidente'' (Mt 8:11), ''muchos profetas y justos'' (Mt 13:17), ''muchas señales'' (Jn 20:30). Sustantivado, οἱ πολλοί significa ''los muchos'' o ''muchos'' (Mt 20:28; Ro 5:15).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75320, 'spa', 'mucho, abundante', 'Mucho, abundante — una gran cantidad o grado de algo, típicamente con sustantivos incontables o abstractos. Noventa y siete apariciones incluyen ''mucho llanto'' (Mt 2:18), ''mucho sufrimiento'' (Mt 16:21), ''mucho fruto'' (Jn 12:24; 15:5) y usos adverbiales como ''orar mucho''. El español distingue perfectamente ''mucho'' (singular incontable) de ''muchos'' (plural contable).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75321, 'spa', 'grande, considerable', 'Grande, considerable — enfatiza magnitud, importancia o intensidad más que mera cantidad. Treinta y seis apariciones donde πολύς funciona casi como sinónimo de μέγας (''grande''): ''grande es vuestra recompensa'' (Mt 5:12), ''una gran multitud'' (Mt 14:14; 20:29), ''gran poder y gloria'' (Mt 24:30). El énfasis recae en lo impresionante o la escala.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75322, 'spa', 'mucho más (comparativo)', 'Mucho más, con mucho — construcciones comparativas que expresan un grado considerablemente mayor, a menudo marcadas por el dativo πολλῷ. Veinticinco apariciones se concentran en Marcos 5 (''le rogaba mucho/con insistencia'') y en los argumentos a fortiori de Pablo (Ro 5:9-10, 15, 17: ''con mucha más razón seremos salvos''). El español emplea ''mucho más'' o ''cuánto más''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75338, 'spa', 'muchas veces (frecuentativo)', 'Muchas veces, a menudo — el sentido frecuentativo, con una aparición clara en Romanos 15:22: ''me he visto impedido muchas veces de ir a vosotros''. El español ''muchas veces'' y el alemán ''vielmals'' emplean expresiones de frecuencia temporal en lugar de simples palabras de cantidad. Aunque raro en este corpus, el uso adverbial frecuentativo de πολύς está bien atestiguado en el griego koiné más amplio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75340, 'spa', 'Compasión abundante', 'La compasión profunda y desbordante del Señor celebrada en Santiago 5:11 tras la historia de Job. Santiago enfatiza que el Señor es ''muy compasivo y misericordioso'', no meramente bondadoso sino profundamente conmovido con tierna misericordia. El término intensifica la compasión normal para expresar la sobreabundancia de la misericordia divina que se reveló al restaurar a Job.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75341, 'spa', 'Costoso y precioso', 'La evidencia interlingüística subraya alto costo y valor. El léxico lo define como «muy caro, costoso» (opuesto a εὐτελής, «barato»), «valioso» y, referido a personas, «pródigo, extravagante». Marcos 14:3 describe un ungüento costoso para ungir a Jesús; 1 Timoteo 2:9 y 1 Pedro 3:4 lo aplican al adorno interior.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75342, 'spa', 'De sumo valor', 'Los equivalentes multilingües destacan un valor supremo. El léxico lo define como «muy venerado» y «de alto precio, muy costoso». Mateo 13:46 describe una perla de gran valor. Juan 12:3 menciona ungüento muy costoso. 1 Pedro 1:7 declara que la fe probada es más preciosa que el oro refinado por el fuego.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75343, 'spa', 'Diversidad de métodos', 'Los diversos métodos por los cuales Dios habló a Israel en Hebreos 1:1: no solo ''en muchas partes'' sino también ''de muchas maneras''. Los profetas recibieron revelación mediante visiones, sueños, teofanías, palabras audibles, señales y actos simbólicos. Esta variedad metodológica contrasta con la revelación única y definitiva en Cristo, la Palabra final del Padre.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75345, 'spa', 'Maldad, perversidad', 'Maldad, perversidad, malicia — la cualidad o condición de depravación moral, que abarca tanto la disposición de un corazón corrupto como sus manifestaciones concretas. Jesús percibe la πονηρία de los fariseos cuando intentan atraparlo (Mateo 22:18) y la diagnostica como la realidad oculta interior tras la religiosidad externa (Lucas 11:39). En Marcos 7:22 se integra en una lista de vicios que rastrean el pecado hasta su origen en el corazón.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75352, 'spa', 'malo, perverso (adjetival)', 'El sentido adjetival dominante: malo, malvado, moralmente perverso. Describe personas (Mat 7:11 ''vosotros, siendo malos''), acciones (Mat 9:4 ''pensamientos malos''), condiciones espirituales (Mat 6:23 ''si tu ojo es malo'') y frutos o resultados (Mat 7:17-18). El español malo/mala, el francés mauvais y el alemán böse traducen esta amplia cualidad moral de manera consistente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75354, 'spa', 'el Maligno (sustantivado)', 'El masculino sustantivado ὁ πονηρός: ''el Maligno'', referido a Satanás como agente personal. Jesús identifica al Maligno como aquel que arrebata la semilla de la palabra (Mat 13:19), siembra cizaña (Mat 13:38), y Juan declara que ''el mundo entero está bajo el Maligno'' (1 Jn 5:19). La petición del Padrenuestro (Mat 6:13) permanece deliberadamente ambigua entre este sentido personal y el mal abstracto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75365, 'spa', 'doloroso, dañino (físico)', 'El sentido físico infrecuente conservado del griego clásico: doloroso, dañino, maligno. En Apocalipsis 16:2, la primera copa produce ''una úlcera mala y dolorosa'' (ἕλκος κακὸν καὶ πονηρόν) sobre quienes llevan la marca de la bestia. El emparejamiento con κακόν confirma que πονηρός denota aquí aflicción corporal y no maldad moral.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75366, 'spa', 'el mal (sustantivo abstracto)', 'El neutro sustantivado τὸ πονηρόν: el mal o la maldad como concepto abstracto. Pablo exhorta a los creyentes a ''aborrecer el mal'' (Ro 12:9) y a ''abstenerse de toda forma de mal'' (1 Ts 5:22). Aquí el mal es una categoría o fuerza, no una cualidad de una persona o cosa específica. El francés le mal y el alemán das Böse captan esta nominalización abstracta.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75368, 'spa', 'Dolor y fatiga', 'Dolor, angustia o aflicción penosa. El sentido clásico de trabajo arduo se concentra en el NT en el sufrimiento intenso: Apocalipsis lo utiliza tres veces para el dolor de los juicios de Dios y su abolición definitiva (Ap 16:10, 16:11, 21:4), mientras que Col 4:13 conserva el sentido antiguo de esfuerzo al describir la lucha ferviente de Epafras en oración por las iglesias.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75369, 'spa', 'Gentilicio póntico', 'Identificador étnico-geográfico de Aquila en Acts 18:2, señalándolo como oriundo del Ponto en el norte de Asia Menor. Esta región albergaba comunidades judías significativas. El origen póntico de Aquila explica su trayecto hacia el oeste, primero a Roma y luego a Corinto, donde conoció a Pablo y se convirtió en su estrecho colaborador ministerial.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75370, 'spa', 'Nombre propio romano', 'Nombre romano usado exclusivamente en el Nuevo Testamento para Poncio Pilato. Aunque en griego clásico πόντιος se relaciona con el mar (epíteto de Poseidón), las apariciones neotestamentarias funcionan como transliteración del latín. Las tres atestaciones abarcan la datación de Lucas (3:1), la confesión apostólica (1 Tim 6:13) y el catálogo de oposición (Hch 4:27).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75374, 'spa', 'ir, marchar (movimiento físico)', 'El sentido nuclear de movimiento físico — ir, marchar, partir o desplazarse de un lugar a otro — que comprende 139 de 154 apariciones. Abarca imperativos (''id por vuestro camino'', Mt 2:8; 8:9; 9:13), movimiento narrativo (''fue a una aldea'', Lc 10:38) y desplazamiento dentro de una escena. Es el valor por defecto para toda locomoción dirigida.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75387, 'spa', 'viajar, emprender camino', 'Énfasis en el viaje o desplazamiento prolongado — 7 apariciones donde el foco está en el proceso de recorrer una ruta o emprender un trayecto, más que en el simple movimiento direccional. Pablo ''yendo camino'' hacia Damasco (Hch 9:3; 22:6; 26:13), Jesús viajando por las aldeas rumbo a Jerusalén (Lc 13:22) y el eunuco etíope ''siguiendo su camino'' tras el bautismo (Hch 8:39).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75388, 'spa', 'andar, conducirse (figurado)', 'Una extensión figurada que significa caminar, conducirse o vivir de cierta manera — 8 apariciones donde el movimiento físico se convierte en metáfora de comportamiento moral o espiritual. Lucas 1:6 ofrece el paradigma: Zacarías e Isabel ''andaban en todos los mandamientos''. En las epístolas el sentido se oscurece: los incrédulos ''anduvieron en lascivia'' (1 P 4:3), los falsos maestros ''andan según la carne'' (2 P 2:10).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75414, 'spa', 'Devastación violenta', 'Se usa en Hechos y Gálatas para describir la persecución violenta de Saulo/Pablo contra la iglesia antes de su conversión. Las formas en imperfecto (Hechos 9:21; Gálatas 1:13, 1:23) subrayan lo sostenido y agresivo de sus ataques. La evidencia señala destrucción total: no mero hostigamiento, sino devastación sistemática de la comunidad cristiana.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75416, 'spa', 'Nombre familiar romano', 'El nombre de familia latino Porcius, referido específicamente a Porcio Festo, quien se convirtió en procurador de Judea según Acts 24:27. Este gobernador romano sucedió a Félix y tuvo que lidiar con el encarcelamiento prolongado de Pablo y su apelación al César. El nombre ancla la narración en la historia administrativa romana.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75418, 'spa', 'Conducta sexual ilícita en sentido amplio, incluyendo fornicación, adulterio e i', 'Conducta sexual ilícita en sentido amplio, incluyendo fornicación, adulterio e incesto, contrapuesta a la fidelidad del pacto. Jesús la menciona como la única causa legítima de divorcio (Mat 5:32; 19:9), y Pablo la incluye entre las obras de la carne. En contextos profético-apocalípticos (Apoc 17-18) el término se extiende metafóricamente a la infidelidad espiritual: la idolatría como prostitución contra Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75425, 'spa', 'Fornicar, cometer inmoralidad', 'Practicar conducta sexual ilícita, incluyendo fornicación, prostitución e inmoralidad sexual en general. Pablo advierte a los corintios que huyan de este pecado, argumentando que es un pecado singular contra el propio cuerpo (1 Co 6:18), y cita el ejemplo catastrófico de Israel en Baal-Peor donde miles murieron (1 Co 10:8). En Apocalipsis el verbo también porta su clásico sentido metafórico veterotestamentario de infidelidad espiritual e idolatría.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75430, 'spa', 'Mujer que practica la prostitución, tanto literalmente (Mt 21', 'Mujer que practica la prostitución, tanto literalmente (Mt 21:31; 1 Co 6:15-16; He 11:31 respecto a Rahab) como figuradamente del imperio idólatra en ''la gran ramera'' del Apocalipsis (Ap 17:1, 5). Un solo lexema abarca ambos registros, literal y metafórico, en las doce ocurrencias neotestamentarias.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75435, 'spa', 'Persona sexualmente inmoral / fornicario', 'Persona sexualmente inmoral / fornicario. Persona caracterizada por la inmoralidad sexual —fornicación, prostitución o conducta sexual ilícita. Aparece predominantemente en listas de vicios y fórmulas de exclusión: los sexualmente inmorales no heredarán el reino de Dios (1 Co 5:9–11; 6:9; Ef 5:5), son advertidos del juicio divino (Heb 13:4; Ap 21:8; 22:15), y Esaú es citado como arquetipo del πόρνος profano (Heb 12:16). Las traducciones existentes en español como ''fornicario'' y ''fornicarios'' reflejan adecuadamente esta carga de exclusión moral y social.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75442, 'spa', 'Lejos, a distancia', 'Lejos, a lo lejos, a distancia, tanto en sentido espacial como metafórico. La cita de Isaías en Mt 15:8 y Mc 7:6 lo emplea para la distancia del corazón respecto a Dios, un uso figurado que el español «lejos» capta con precisión. Lc 14:32 presenta a un rey enviando delegados mientras el enemigo está todavía lejos, y Lc 24:28 describe a Jesús aparentando seguir más lejos por el camino de Emaús.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75444, 'spa', 'Tela púrpura', 'Tela, tejido o vestidura de púrpura: el lujoso tinte y textil que simboliza realeza, riqueza o alto estatus. En Marcos 15:17 y 15:20, los soldados visten a Jesús de púrpura para burlarse de su realeza, invirtiendo el símbolo del poder imperial. Lucas 16:19 caracteriza al hombre rico por su uso diario de púrpura, señal de riqueza desmedida. Apocalipsis 18:12 cataloga la púrpura entre las mercancías de Babilonia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75445, 'spa', 'De color púrpura', 'Purpúreo, teñido de púrpura: describe vestiduras o tejidos del costoso púrpura tirio. Juan 19:2 y 19:5 lo usan para el manto puesto sobre Jesús en burla, mientras que Apocalipsis 17:4 y 18:16 lo aplican al opulento atuendo de la Babilonia simbólica. Junto con la forma sustantiva (G4209), este adjetivo completa el campo semántico del púrpura en el NT.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75446, 'spa', 'Comerciante de púrpura', 'La profesión de Lidia en Acts 16:14 como comerciante de artículos lujosos de púrpura. Tiatira era célebre por su industria de teñido, y Lidia había extendido este comercio hasta Filipos. La naturaleza costosa del tinte púrpura, que requería miles de moluscos para obtener pequeñas cantidades, significaba que los comerciantes de púrpura atendían a una clientela de élite.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75447, 'spa', 'Frecuencia interrogativa', 'Aparece en contextos donde Jesús habla de acciones repetidas. En Mateo 18:21, Pedro pregunta cuántas veces debe perdonar, provocando la respuesta «setenta veces siete». En los lamentos sobre Jerusalén (Mateo 23:37; Lucas 13:34), Jesús expresa cuántas veces quiso reunir a sus hijos como la gallina recoge a sus polluelos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75448, 'spa', 'Bebida literal', 'Se refiere al acto literal de beber como necesidad física o asunto religioso. En Juan 6:55, Jesús declara que su sangre es «verdadera bebida» en el discurso eucarístico. Romanos 14:17 subordina el comer y el beber a la justicia, la paz y el gozo en el Espíritu Santo. Colosenses 2:16 advierte contra juzgar en materia de comida y bebida.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75449, 'spa', 'Interrogativo de grado o extensión', 'Interrogativo de grado o extensión: ''¿cuánto?'', ''¿cuán grande?'', ''¿cuánto tiempo?'', usado para preguntar sobre magnitud, duración o intensidad, especialmente prominente en argumentos a fortiori (cuánto más). Jesús pregunta cuánto más vale un hombre que una oveja (Mat 12:12), y cuán grande es la oscuridad cuando falla la luz interior (Mat 6:23). Marcos 9:21 lo usa temporalmente: ''¿Cuánto tiempo lleva así?''');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75450, 'spa', 'Interrogativo de número o conteo', 'Interrogativo de número o conteo: ''¿cuántos?'', preguntando por cantidades discretas y contables. Jesús pregunta a los discípulos cuántos panes tienen (Mat 15:34; Mar 6:38) y luego cuántas cestas de fragmentos recogieron (Mat 16:9-10). Pilato pregunta a Jesús cuántos cargos hay contra él (Mat 27:13). El español ''cuántos'' (plural) maneja este sentido enumerativo con naturalidad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75454, 'spa', 'Un cuerpo natural de agua que fluye, desde arroyos modestos hasta grandes ríos c', 'Un cuerpo natural de agua que fluye, desde arroyos modestos hasta grandes ríos como el Jordán y el Éufrates. Se usa literalmente para cursos de agua geográficos donde tienen lugar bautismos (Mt 3:6; Mr 1:5) y donde las inundaciones amenazan construcciones (Mt 7:25). También se emplea en imágenes apocalípticas y proféticas -- ríos de agua viva (Jn 7:38) y el río de la vida (Ap 22:1). El español río cubre todo el espectro, desde el arroyo hasta el gran cauce.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75458, 'spa', 'Arrastrado por torrente', 'El destino pretendido en Revelation 12:15 cuando el dragón escupe una inundación para arrastrar a la mujer. El término captura la indefensión de quedar atrapado en un torrente, llevado por fuerzas que escapan a todo control. La intervención milagrosa de la tierra salva a la mujer de esta destrucción acuática, frustrando el ataque del dragón.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75459, 'spa', '¿Qué clase de?', '¿Qué clase de? ¿Qué tipo de? — adjetivo interrogativo que indaga sobre la naturaleza, cualidad o carácter de algo, generalmente con matices de asombro. En Mt 8:27 los discípulos preguntan «¿qué clase de hombre es este?», expresando admiración ante la autoridad de Jesús sobre la naturaleza. En Mr 13:1 expresa reverencia ante la grandiosidad del templo. En Lc 1:29 María reflexiona sobre «qué clase de saludo sería este».');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75465, 'spa', 'en otro tiempo, antes', 'en otro tiempo, antes');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75466, 'spa', 'alguna vez, jamás', 'alguna vez, jamás');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75468, 'spa', 'por fin, al cabo', 'por fin, al cabo');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75472, 'spa', '¿cuándo? (interrogativo)', '¿cuándo? (interrogativo)');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75473, 'spa', 'alguna vez (no sea que)', 'alguna vez (no sea que)');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75475, 'spa', 'acaso, quizás', 'acaso, quizás');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75478, 'spa', 'Partícula disyuntiva', 'El «si» en John 7:17 que introduce dos alternativas sobre la fuente de la enseñanza de Jesús: si proviene de Dios o es de origen propio. Esta partícula estructura la elección binaria que Jesús ofrece a sus oyentes. Jesús promete que la obediencia moral proporciona la clave epistemológica para discernir el origen divino de su doctrina.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75479, 'spa', 'copa, vaso para beber', 'copa, vaso para beber');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75482, 'spa', 'Dar una bebida a alguien para que la consuma, ya sea literalmente ofreciendo un ', 'Dar una bebida a alguien para que la consuma, ya sea literalmente ofreciendo un vaso de agua fría (Mt 10:42) o figuradamente nutriendo con sustento espiritual. Las traducciones en distintos idiomas emplean consistentemente expresiones de hospitalidad personal. La parábola de las ovejas y los cabritos (Mt 25:35-42) convierte este acto en medida de la fe.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75483, 'spa', 'Suministrar agua a plantas, cultivos o terreno con el fin de hacerlos crecer — r', 'Suministrar agua a plantas, cultivos o terreno con el fin de hacerlos crecer — regar o irrigar. La metáfora de Pablo en 1 Corintios 3:6-8 emplea este sentido agrícola: él plantó, Apolos regó, pero Dios dio el crecimiento. Se distingue claramente del sentido interpersonal de ''dar de beber'', confirmando la frontera semántica entre hospitalidad y cultivo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75493, 'spa', 'Ciudad portuaria italiana', 'La ciudad portuaria italiana de Puteoli donde Pablo desembarcó en Hechos 28:13 durante su viaje a Roma. Situada en la bahía de Nápoles, era el punto de llegada de navíos de grano desde Alejandría. La evidencia multilingüe muestra transliteración (''Potioloi'', ''Potiólous'') o equivalentes modernos (''Pouzzoles''). La presencia de creyentes allí demuestra el alcance temprano del cristianismo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75494, 'spa', 'Fiestas de bebida', 'Las fiestas de bebida enumeradas entre los excesos gentiles en 1 Pedro 4:3 que los creyentes han renunciado. Estas reuniones giraban en torno al consumo excesivo de vino, conduciendo a la embriaguez e inmoralidad. Las glosas multilingües identifican el enfoque en la bebida (''drinking-parties'', ''fiestas-de-beber'', ''Trinkgelage''). Pedro las agrupa con la sensualidad, las pasiones y la idolatría.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75495, 'spa', 'Dónde', 'Dónde — adverbio interrogativo o relativo de lugar que pregunta o indica ubicación. María Magdalena vio «dónde» fue puesto Jesús (Mr 15:47); los discípulos preguntan «dónde» se hospeda Jesús (Jn 1:39); quien odia a su hermano no sabe «adónde» va (1 Jn 2:11). El español distingue entre «dónde» y «adónde», reflejando un matiz direccional que el griego deja implícito.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75496, 'spa', 'En algún lugar', 'En algún lugar, en alguna parte — adverbio espacial o referencial indefinido. En Hch 27:29 los marineros sospechan que se acercan a «algún lugar» (tierra). Hebreos lo utiliza para citas bíblicas imprecisas: «alguien testificó en algún lugar» (Heb 2:6; 4:4). Las expresiones españolas «en alguna parte» y «en algún lugar» transmiten fielmente esa misma imprecisión deliberada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75497, 'spa', 'Aproximadamente', 'Aproximadamente, como — se usa con números para indicar una estimación aproximada. En Ro 4:19, Abraham tenía «como» (πού) cien años. El español «aproximadamente» y «como» hacen explícita la función aproximativa, mientras que otras lenguas tratan esta acepción como la misma vaguedad indefinida del sentido espacial.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75499, 'spa', '¿dónde? (interrogativo de lugar)', '¿dónde? (interrogativo de lugar)');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75500, 'spa', 'en algún lugar (uso indefinido)', 'en algún lugar (uso indefinido)');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75501, 'spa', 'Cristiano romano Pudente', 'El cristiano romano Pudente que envía saludos en 2 Timoteo 4:21 durante el encarcelamiento final de Pablo. Formaba parte de la comunidad cristiana romana que apoyó al apóstol. La evidencia multilingüe muestra transliteración (''Poudes'', ''Poudēs'') o la forma latina (''Pudens''). Su mención junto a Lino y Claudia sugiere pertenencia al círculo de liderazgo en Roma.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75502, 'spa', 'pie', 'El pie físico, la extremidad inferior del cuerpo usada para estar de pie y caminar. En el Nuevo Testamento, πούς lleva una carga simbólica intensa: caer a los pies de alguien señala reverencia o súplica (Mc 5:22; Ap 1:17), lavar los pies expresa servicio humilde (Jn 13:5-14), sacudir el polvo de los pies pronuncia juicio profético (Mat 10:14), y los enemigos puestos ''bajo los pies'' denotan sujeción total (1 Co 15:25-27).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75505, 'spa', 'Asunto, cosa, hecho', 'Asunto, cosa, hecho. Un asunto, cosa, hecho o acción — el sentido general que abarca acontecimientos concretos, disputas legales, negocios prácticos y realidades abstractas. Se usa para eventos que han tenido lugar (Lc 1:1; Hch 5:4), un tema de acuerdo en oración (Mt 18:19), un caso legal presentado ante tribunales (1 Co 6:1), un asunto comercial o interpersonal (1 Ts 4:6; Ro 16:2), y las realidades subyacentes aprehendidas por la fe (Heb 6:18; 11:1).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75512, 'spa', 'Asuntos civiles', 'Los asuntos civiles y preocupaciones comerciales que los soldados evitan en 2 Timoteo 2:4 para mantener su enfoque en la aprobación de su comandante. La metáfora militar de Pablo advierte contra el involucramiento enredante en asuntos mundanos que distraen de la misión espiritual. Las glosas multilingües varían (''affairs'', ''negocios'', ''Geschaeft''), pero todas captan las preocupaciones prácticas y terrenales.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75513, 'spa', 'Negociar e invertir', 'La orden del amo de ''negociar'' con las minas en Lucas 19:13, esperando que los siervos comercien e inviertan activamente durante su ausencia. El verbo implica participación emprendedora, no mayordomía pasiva. La evidencia multilingüe muestra vocabulario comercial (''Do-business'', ''Negociad'', ''faire-des-affaires'', ''Πραγματεύσασθε''). La parábola recompensa a quienes multiplican los recursos mediante un comercio activo y prudente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75514, 'spa', 'Pretorio, residencia del gobernador', 'Residencia oficial del gobernador romano o cuartel militar, y por metonimia la propia guardia pretoriana. En los relatos del juicio, los Evangelios sitúan la sentencia de Jesús dentro de este recinto (Jn 18:28 contrasta la negativa de los judíos a entrar por razones de pureza). El uso de Pablo en Fil 1:13 extiende el término para abarcar los cuarteles de la guardia imperial.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75519, 'spa', 'Hecho, obra, práctica', 'Hecho, acción o patrón de conducta visto en su dimensión moral. En Mt 16:27 designa la totalidad de las acciones ante el juicio final; en Rom 8:13 y Col 3:9 se estrecha a prácticas pecaminosas que deben ser mortificadas; en Hch 19:18 los conversos confiesan sus hechos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75521, 'spa', 'Función, papel', 'La función específica u oficio que una parte desempeña dentro de un todo organizado. En Rom 12:4, Pablo escribe que los miembros del cuerpo no comparten la misma πρᾶξις; aquí «función» capta el propósito asignado a cada componente, apoyándose en el uso clásico griego de πρᾶξις como tarea u oficio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75525, 'spa', 'practicar habitualmente, hacer repetidamente', 'practicar habitualmente, hacer repetidamente');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75526, 'spa', 'hacer, realizar una acción concreta', 'hacer, realizar una acción concreta');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75533, 'spa', 'cobrar, recaudar pagos', 'cobrar, recaudar pagos');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75535, 'spa', 'ser hecho, ser realizado (pasivo)', 'ser hecho, ser realizado (pasivo)');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75557, 'spa', 'Manso y apacible', 'Manso, apacible, de temperamento moderado: describe una disposición de humilde contención en lugar de autoafirmación agresiva. Jesús reclama esta cualidad para sí mismo (Mt 11:29) y bendice a quienes la poseen (Mt 5:5, eco del Sal 37:11). El cumplimiento profético en Mateo 21:5 (citando Zac 9:9) presenta al Rey-Mesías llegando con mansedumbre deliberada. En 1 Pedro 3:4 caracteriza un espíritu precioso ante Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75558, 'spa', 'La virtud de la autocontención mansa y humilde — poder bajo control, no debilida', 'La virtud de la autocontención mansa y humilde — poder bajo control, no debilidad pasiva. Fruto del Espíritu (Gá 5:23), emparejada con la humildad y la paciencia (Ef 4:2; Col 3:12) y modelada por Cristo (2 Co 10:1). Refleja un carácter apacible capacitado por el Espíritu, convergente en todas las lenguas bajo un solo concepto de dulzura moderada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75562, 'spa', 'Convenir, ser apropiado', 'Convenir, ser apropiado o decoroso — verbo impersonal o cuasi-impersonal que afirma que algo es adecuado, digno o moralmente correcto en una situación dada. Jesús lo invoca en su bautismo para explicar por qué Juan debe acceder: «conviene que cumplamos toda justicia» (Mt 3:15). Pablo lo utiliza para el decoro en la adoración (1 Co 11:13: «¿es apropiado que una mujer ore sin cubrirse?») y la conducta ética cristiana.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75568, 'spa', 'Asamblea de ancianos', 'Designa una asamblea institucional de ancianos con autoridad. En Lucas 22:66 se refiere al consejo judío que interrogó a Jesús. Hechos 22:5 menciona al sumo sacerdote y «todo el consejo de ancianos» como testigos de la persecución anterior de Pablo. En 1 Timoteo 4:14 alude al presbiterio cristiano que impuso las manos sobre Timoteo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75569, 'spa', 'anciano, líder comunitario', 'El sentido institucional dominante: un dirigente reconocido u oficial que porta el cuasi-título de ''anciano'' dentro de la gobernanza judía o cristiana primitiva. En los Evangelios, estos ancianos conspiran con los principales sacerdotes contra Jesús (Mat 16:21; 26:3); en Hechos y las Epístolas pastorean las congregaciones locales. La evidencia multilingüe es notablemente estable: inglés elders, francés ancien, alemán Älteste.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75571, 'spa', 'antepasado, persona de antaño', 'Personas de tiempos pasados, los venerados antepasados de la fe. Hebreos 11:2 elogia a ''los ancianos'' que recibieron aprobación divina, trascendiendo todo cargo institucional para evocar la gran nube de testigos. Las mismas traducciones —ancianos, ancien, Älteste— se reutilizan, de modo que solo el contexto distingue el honor ancestral del oficio comunitario.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75573, 'spa', 'mayor en edad', 'Un comparativo directo: ''mayor en edad'', sin implicar cargo oficial alguno. El hijo mayor de la parábola del hijo pródigo (Lc 15:25) y el consejo pastoral sobre los hombres mayores en 1 Timoteo 5:1 emplean este sentido puramente etario. El español mayor (en lugar de anciano) y el inglés older señalan el alejamiento del significado institucional.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75576, 'spa', 'mujer mayor', 'La contraparte femenina que describe a las mujeres mayores de la comunidad. En 1 Timoteo 5:2, Pablo aconseja a Timoteo tratar ''a las ancianas como a madres'', donde el español ancianas y el inglés older women marcan una clara distinción de género y rol respecto del anciano-como-líder masculino.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75579, 'spa', 'Hombre de edad', 'Designa a un varón individual de edad avanzada. Zacarías se identifica como «anciano» cuando el ángel anuncia el nacimiento de Juan (Lucas 1:18). Tito 2:2 establece expectativas de conducta para los «ancianos» en la comunidad cristiana. En Filemón 1:9, Pablo se presenta como «Pablo, ya anciano», aunque algunos interpretan el término como «embajador».');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75580, 'spa', 'Ancianas mentoras', 'Las mujeres mayores de Titus 2:3 que deben mostrar una conducta reverente y enseñar a las más jóvenes. Pablo las presenta como mentoras espirituales cuya edad y experiencia las capacitan para instruir. Las traducciones multilingües identifican consistentemente la edad (''older-women'', ''ancianas'', ''aeltere-Frau''). Su vocación implica modelar la piedad y guiar activamente a la siguiente generación en la vida cristiana práctica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75581, 'spa', 'Caída de bruces', 'La manera en que Judas cayó en Acts 1:18 —de cabeza o de bruces— como parte del relato gráfico de su muerte. El término contrasta con caer de espaldas, enfatizando la orientación descendente y hacia adelante. La evidencia multilingüe varía (''headlong'', ''de-cabeza'', ''tête-baissée''), señalando la naturaleza violenta y descendente del suceso. Junto con el reventarse de su cuerpo, subraya el horroroso juicio divino.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75582, 'spa', 'Martirio por aserrado', 'El método de martirio en Hebrews 11:37 —ser aserrado en dos— que representa la persecución extrema. La tradición judía sostenía que Isaías fue aserrado en dos con una sierra de madera durante el reinado de Manasés. Las traducciones multilingües transmiten la acción horrorosa (''they-were-sawn-in-two'', ''fueron-aserrados'', ''scier'', ''zersaegen''). Este sufrimiento extremo demuestra el altísimo costo de la fe y hasta dónde llegaron los testigos de Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75583, 'spa', 'Adverbio y conjunción temporal que indica que un evento o estado precede a otro ', 'Adverbio y conjunción temporal que indica que un evento o estado precede a otro en el tiempo. En contextos narrativos enmarca momentos en que la secuencia es determinante: la predicción de la negación de Pedro (Mt 26:34, 75; Mr 14:30, 72) y las circunstancias de la concepción de Jesús (Mt 1:18). Se usa tanto de forma absoluta (''antes'') como con cláusulas subordinadas (''antes de que suceda algo''). Las 13 ocurrencias expresan un único sentido temporal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75585, 'spa', 'Prisca, líder eclesial', 'Identifica a Prisca, esposa de Aquila y líder clave en la iglesia primitiva. Romanos 16:3 envía saludos a «Prisca y Aquila, mis colaboradores en Cristo Jesús». 1 Corintios 16:19 transmite saludos de «Aquila y Prisca, junto con la iglesia que se reúne en su casa». 2 Timoteo 4:19 les envía saludos nuevamente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75586, 'spa', 'Priscila en Hechos', 'Identifica a Priscila en la narrativa de Lucas en Hechos. Hechos 18:2 la presenta cuando Pablo conoce a Aquila y Priscila en Corinto, habiendo llegado de Roma. Hechos 18:18 menciona que Pablo navegó con «Priscila y Aquila». Hechos 18:26 describe cómo Priscila y Aquila instruyeron a Apolos y «le expusieron con mayor exactitud el camino de Dios».');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75587, 'spa', 'antes, delante de', 'antes, delante de');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75593, 'spa', 'Ir delante espacialmente, guiando el camino o caminando al frente de otros', 'Ir delante espacialmente, guiando el camino o caminando al frente de otros. La estrella sobre Belén guiaba a los magos (Mt 2:9); las multitudes van delante de Jesús hacia Jerusalén (Mt 21:9); Jesús promete ir delante de sus discípulos a Galilea tras la resurrección (Mt 26:32). Este es el sentido más frecuente, con trece apariciones aproximadas en el NT.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75594, 'spa', 'Llevar a alguien adelante o sacarlo, actuando transitivamente sobre una persona', 'Llevar a alguien adelante o sacarlo, actuando transitivamente sobre una persona. En Hechos 12:6, Herodes está por ''sacar'' a Pedro; en Hechos 16:30 el carcelero ''saca'' a Pablo y Silas. Hechos 25:26 lo usa para presentar a un prisionero ante una asamblea. Cuatro ocurrencias llevan este matiz causativo, donde el sujeto mueve activamente a otra persona.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75601, 'spa', 'Preceder en el tiempo o en orden lógico, refiriéndose a algo anterior', 'Preceder en el tiempo o en orden lógico, refiriéndose a algo anterior. Primera Timoteo 1:18 recuerda las profecías que ''precedieron'' acerca de Timoteo, y Hebreos 7:18 habla de un mandamiento precedente que fue abrogado. Este sentido aparece tres veces, siempre en argumentos epistolares sobre lo que vino primero.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75607, 'spa', 'Propósito deliberado', 'La toma de decisión deliberada que Pablo recomienda en 2 Corinthians 9:7 respecto a la ofrenda económica. Cada persona debe dar ''según lo que haya propuesto en su corazón'', una resolución considerada e intencional y no una reacción impulsiva. La evidencia multilingüe muestra vocabulario de propósito y decisión (''he-has-purposed'', ''ha-propuesto'', ''préméditer'', ''vorher-waehlen''). Pablo contrasta esta intencionalidad reflexiva con la reluctancia o la coacción.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75608, 'spa', 'Acusación previa', 'La acusación previa de Pablo en Romans 3:9 de que toda la humanidad —tanto judíos como gentiles— se encuentra bajo la condenación del pecado. El carácter previo del verbo apunta a su argumentación anterior en Romans 1-2. Las traducciones multilingües enfatizan la acusación previa (''we-already-charged'', ''ya-hemos-acusado'', ''accuser-d''avance'', ''vorher-beschuldigen''). Pablo recuerda a sus lectores que ya estableció esta acusación universal contra el pecado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75609, 'spa', 'Oír previamente el evangelio', 'La audición previa del evangelio referida en Colosenses 1:5: los colosenses «oyeron antes» acerca de su esperanza celestial mediante la palabra de verdad. Pablo les recuerda el evangelio que ya habían recibido de Epafras. La evidencia multilingüe resalta la prioridad temporal (''oísteis-antes'', ''vorher-hören''). Esta proclamación evangélica previa y auténtica debía anclarlos frente a las nuevas enseñanzas falsas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75611, 'spa', 'Portal o vestíbulo', 'El portal o vestíbulo al que Pedro se retira en Marcos 14:68 tras su primera negación de Cristo. Este espacio de transición entre la calle y el patio se convierte en el escenario de la vacilación de Pedro. Las glosas multilingües identifican la estructura de entrada (''gateway'', ''portal'', ''vestibule'', ''Vorhof''). La ubicación física de Pedro refleja su estado espiritual: ni plenamente dentro ni completamente fuera.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75612, 'spa', 'Avanzar o progresar', 'Ir hacia adelante o avanzar, ya sea en el espacio físico o en el transcurso del tiempo. Dos patrones de uso aparecen en el NT: movimiento espacial, donde Jesús «siguió adelante» por la orilla de Galilea para llamar a Jacobo y Juan (Mt 4:21; Mr 1:19), y avance temporal, donde la expresión προβεβηκότες ἐν ταῖς ἡμέραις («avanzados en sus días») describe a los ancianos Zacarías e Isabel (Lc 1:7, 18) y a la profetisa Ana (Lc 2:36).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75614, 'spa', 'Puerta de las Ovejas', 'La Puerta de las Ovejas junto a la cual se hallaba el estanque de Betesda en Juan 5:2. Esta puerta de Jerusalén servía como punto de entrada para las ovejas destinadas al sacrificio del Templo. Las glosas multilingües identifican la puerta (''sheep-gate'', ''de-ovejas'', ''des-brebis'', ''Schaftor''). El lugar resulta teológicamente sugerente: Jesús sana cerca de la puerta asociada con los corderos sacrificiales, prefigurando su propio papel como Cordero de Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75615, 'spa', 'oveja', 'oveja');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75619, 'spa', 'Instigar o inducir', 'La instigación de la hija de Herodías en Mateo 14:8 cuando solicita la cabeza de Juan el Bautista. Ella no concibió esta horrorosa petición por sí misma, sino que fue «instruida por su madre». Las glosas multilingües muestran diversos enfoques (''having-been-prompted'', ''habiendo-sido-instruida'', ''pousser''), pero todos transmiten la instigación externa. El término expone la manipulación de Herodías, quien usó a su hija como instrumento de venganza.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75620, 'spa', 'Prever y proveer', 'La evidencia multilingüe converge en el aspecto temporal de prioridad (alemán/francés ''voraussehen'', español ''previsto''). Hebreos 11:40 habla de la previsión providencial de Dios al planificar la historia redentora para que todas las generaciones compartieran la misma perfección mediante Cristo. La voz media enfatiza la participación personal de Dios en esta provisión anticipada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75621, 'spa', 'Cometido previamente', 'La evidencia interlingüística muestra ''previamente'' y ''de antemano'' como significado central (español ''cometidos anteriormente'', francés ''précédent'', alemán ''vorher geschehen''). El argumento de Pablo en Romanos 3:25 depende de esta distinción temporal: la justicia de Dios se demuestra al tratar los pecados pasados mediante el sacrificio de Cristo, mostrando que la paciencia divina no era indiferencia sino demora intencional.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75622, 'spa', 'Conocer de antemano', 'Conocer previamente o saber de antemano: se aplica tanto al conocimiento previo divino como humano, aunque el NT lo usa predominantemente respecto al conocimiento soberano de Dios. En Romanos 8:29, el preconocimiento de Dios inicia toda la cadena de salvación (conoció → predestinó → llamó → justificó → glorificó), sugiriendo una relación personal y electiva más que una mera percepción cognitiva. Romanos 11:2 asegura que Dios no ha desechado al pueblo que conoció de antemano.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75625, 'spa', 'Escribir o exhibir previamente', 'Escribir de antemano o exponer públicamente por escrito, ya sea con prioridad temporal o como proclamación pública. En Gal 3:1, Cristo crucificado fue «expuesto públicamente» ante los gálatas como en un edicto oficial. Rom 15:4 señala las Escrituras «escritas con anterioridad» para instrucción. Ef 3:3 remite a lo escrito previamente. Judas 1:4 habla de personas «designadas desde antiguo» para juicio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75626, 'spa', 'Manifiesto y evidente', 'Describe realidades morales que ya son patentes y obvias. Primera Timoteo 5:24 afirma que los pecados de algunos son evidentes y los preceden al juicio; el versículo siguiente añade que las buenas obras también son manifiestas. Hebreos 7:14 señala que es evidente que nuestro Señor descendió de Judá.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75627, 'spa', 'Dar primero', 'Todas las traducciones capturan el elemento de prioridad (''dio primero'', ''donner d''abord'', ''vorher übergeben''). En Romanos 11:35, Pablo usa este verbo para demoler toda justicia por obras: nadie ha dado a Dios primero, nadie puede exigir retribución. Todo dar humano es respuesta a la generosidad divina previa, nunca el acto que crea obligación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75628, 'spa', 'Traidor y delator', 'Identifica a quienes traicionan a otros, especialmente en contextos de fracaso moral y persecución. Lucas 6:16 señala a Judas Iscariote como traidor. Hechos 7:52 llama a los perseguidores de los profetas «traidores y homicidas» del Justo. Segunda Timoteo 3:4 incluye a los traidores entre las características de los últimos tiempos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75629, 'spa', 'Precursor', 'Las traducciones preservan la imagen de ''correr delante'' (español ''precursor'', francés ''précurseur'', alemán ''Vorläufer''). El autor de Hebreos usa esta metáfora para asegurar a los creyentes que Jesús ya entró a la presencia de Dios por nosotros, garantizando el acceso que seguiremos. A diferencia del sumo sacerdote que entraba solo y temporalmente, Jesús entra como precursor permanente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75630, 'spa', 'Esperar de antemano', 'Los glosarios multilingües enfatizan el aspecto temporal (''que antes esperamos'', ''vorher hoffen''). Ya sea que Pablo se refiera a la prioridad judía en la salvación o a quienes ya eran creyentes, el verbo subraya que algunos habían fijado su esperanza en Cristo, convirtiéndose en la vanguardia de una comunidad de esperanza mayor que abarcaría todas las naciones.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75631, 'spa', 'Predecir', 'La evidencia interlingüística muestra ''predecir'' como significado primario (español ''predijo'', francés ''prédire''). El argumento de Pedro en Hechos 1:16 depende de reconocer los salmos davídicos como profecías anticipatorias, no meros lamentos históricos. Que la Escritura ''predijo'' por el Espíritu significa que la traición no fue accidente sino algo anticipado y declarado dentro del plan redentor de Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75634, 'spa', 'Ir adelante, preceder', 'Ir por delante, avanzar antes que otros o proseguir hacia adelante, ya sea viajando físicamente al frente de un grupo o precediendo a alguien en sentido preparatorio o anticipatorio. En contextos narrativos describe a Jesús retirándose adelante para orar (Mt 26:39; Mr 14:35), a las multitudes corriendo por delante al destino (Mr 6:33) y a Judas guiando al grupo de arresto (Lc 22:47). Proféticamente, describe la misión precursora de Juan el Bautista.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75645, 'spa', 'Propósito, plan o resolución deliberada, ya sea divina o humana', 'Propósito, plan o resolución deliberada, ya sea divina o humana. Usado predominantemente del decreto eterno y el consejo predeterminado de Dios (Ro 8:28; 9:11; Ef 1:11; 3:11; 2 Ti 1:9), pero también de la intención humana, como Bernabé exhortando a los creyentes de Antioquía a permanecer fieles ''con firmeza de corazón'' (Hch 11:23) y los planes de viaje de Pablo (Hch 27:13).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75646, 'spa', 'El acto de presentar o colocar delante, específicamente los ''panes de la proposi', 'El acto de presentar o colocar delante, específicamente los ''panes de la proposición'' (pan de la Presencia) dispuestos sobre la mesa sagrada en el tabernáculo o el templo. Término cúltico-ritual que aparece en los relatos sinópticos de David comiendo los panes consagrados (Mt 12:4; Mr 2:26; Lc 6:4) y en la descripción del mobiliario del tabernáculo (He 9:2).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75652, 'spa', 'Prontitud de ánimo', 'Disposición entusiasta o buena voluntad para comprometerse o contribuir. Los usos en 2 Corintios 8-9 vinculan este término con la teología de la generosidad: Pablo elogia la disposición de los corintios (8:11-12, 19) y la comunica a los macedonios (9:2). El principio de 8:12 es notable: si la disposición está presente, la ofrenda es aceptable según lo que se tiene.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75653, 'spa', 'Dispuesto y presto', 'Describe el estado de estar dispuesto, preparado o deseoso de actuar. En Mateo 26:41 y Marcos 14:38, Jesús dice a los discípulos que el espíritu está dispuesto pero la carne es débil. Romanos 1:15 expresa el anhelo de Pablo: está presto a predicar el evangelio también a los que están en Roma.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75655, 'spa', 'Dirigir, presidir', 'Estar al frente de otros en posición de autoridad, administrando, dirigiendo o presidiendo con atención y cuidado. Pablo presenta la administración del hogar como campo de prueba para el liderazgo eclesial: ''Si alguien no sabe gobernar su propia casa, ¿cómo cuidará de la iglesia de Dios?'' (1 Ti 3:5). El término abarca tanto la función de gobierno como la actitud de servicio diligente que debe acompañarla.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75663, 'spa', 'Estar puesto delante', 'Yacer o estar puesto delante de alguien, hallarse presente o expuesto como objeto de búsqueda o ejemplo. La voz pasiva destaca que algo ha sido colocado ante una persona por otro agente, a menudo Dios. En Heb 12:2, el gozo «puesto delante» de Jesús motivó su perseverancia en la cruz. Heb 12:1 invita a correr la carrera «propuesta».');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75665, 'spa', 'Progreso espiritual', 'Se refiere al avance observable en realidades espirituales. Filipenses 1:12 afirma que el encarcelamiento de Pablo redundó en mayor progreso del evangelio. Filipenses 1:25 habla del provecho y gozo en la fe de los filipenses. Primera Timoteo 4:15 exhorta a Timoteo a practicar estas cosas para que su aprovechamiento sea manifiesto a todos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75666, 'spa', 'Avanzar, progresar', 'Avanzar, progresar o ir hacia adelante en sentido metafórico. El sentido literal de «abrir camino cortando» ha dado paso por completo al uso figurado en el NT: Jesús avanza en sabiduría (Lc 2:52), la noche escatológica avanza hacia el amanecer (Rom 13:12), Pablo antes progresaba en el judaísmo (Gal 1:14) y las palabras impías avanzan como gangrena (2 Ti 2:16).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75672, 'spa', 'Anticipar o ser sorprendido', 'Describe tomar algo por adelantado o ser sorprendido en un acto. Marcos 14:8 dice que la mujer se anticipó a ungir el cuerpo de Jesús para la sepultura. Primera Corintios 11:21 critica a quienes toman su propia cena antes de tiempo. Gálatas 6:1 habla de restaurar a quien sea sorprendido en alguna falta.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75673, 'spa', 'Decir o comunicar algo de antemano, refiriéndose a una declaración previa o pred', 'Decir o comunicar algo de antemano, refiriéndose a una declaración previa o predicción profética sin conllevar necesariamente un tono de advertencia. Jesús dice a sus discípulos ''os lo he dicho de antemano'' sobre los engaños venideros (Mt 24:25) y los sufrimientos del fin (Mr 13:23). Pablo cita las palabras previas de Isaías en Ro 9:29 y apela a lo que ya había dicho en 2 Co 13:2.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75678, 'spa', 'Advertir de antemano con urgencia admonitoria o moral, donde la declaración prev', 'Advertir de antemano con urgencia admonitoria o moral, donde la declaración previa lleva el peso de una amonestación solemne. Se usa en Gá 5:21, donde Pablo dice ''os advierto de antemano, como ya os advertí antes, que los que practican tales cosas no heredarán el reino de Dios''. La expresión duplicada subraya la gravedad del aviso.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75687, 'spa', 'Provision responsable', 'Describe la provision reflexiva y la planificacion, especialmente en relacion con la conducta honorable y el cuidado familiar. Romanos 12:17 instruye a los creyentes a procurar lo bueno delante de todos. Segunda Corintios 8:21 reitera este principio de proveer lo honesto ante Dios y ante los hombres. Primera Timoteo 5:8 advierte severamente que quien no provee para los suyos ha negado la fe.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75689, 'spa', 'Prever o contemplar', 'Ver de antemano, prever, o mantener constantemente ante los ojos. Hechos 2:25 (citando Sal 16:8) capta el sentido de «delante de mi rostro»: David mantenía al Señor siempre a la vista, en una postura de atención sostenida. Hechos 2:31 se desplaza a la previsión profética: David previó la resurrección del Cristo. Hechos 21:29 es más sencillo: habían visto antes a Trófimo en la ciudad. Gálatas 3:8 personifica a la Escritura misma como agente que prevé.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75690, 'spa', 'Predestinar, preordenar', 'Determinar o designar de antemano, predestinar; se usa exclusivamente del decreto soberano de Dios sobre la salvación y la historia. En Rom 8:29-30, Dios predestinó a los suyos a ser conformados a la imagen de Cristo; en Ef 1:5 y 1:11, son predestinados para adopción y herencia; en 1 Co 2:7, la sabiduría divina fue predestinada antes de los siglos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75696, 'spa', 'Encaminar, acompañar', 'Escoltar a alguien en su viaje, ayudarlo a partir proveyéndole de provisiones, compañía o apoyo en oración, una práctica característica de la hospitalidad cristiana primitiva. Aparece en Hechos describiendo a iglesias que envían adelante a misioneros (Hch 15:3; 20:38; 21:5) y en las epístolas donde Pablo pide ser ayudado en su camino (Ro 15:24; 1 Co 16:6, 11; 2 Co 1:16; Tit 3:13; 3 Jn 6).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75706, 'spa', 'direccion: a, hacia', 'Sentido direccional primario con acusativo: ''a,'' ''hacia,'' indicando movimiento u orientacion hacia una persona, lugar o meta. Con 520 apariciones es el uso predominante. Mt 3:5 (''salian a el''), Mt 3:13 (''Jesus vino al Jordan''). Jn 1:1 (''el Verbo estaba con Dios'') parte de aqui pero trasciende la mera direccionalidad hacia una relacion de intimidad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75707, 'spa', 'proposito: para', 'Proposito o finalidad: ''para,'' ''a fin de,'' ''con miras a.'' Mt 6:1 (''no practiqueis vuestra justicia delante de los hombres para ser vistos'') y Mt 5:28 (''todo el que mira a una mujer para codiciarla''). Con 113 apariciones, πρός compite con εἰς para marcar proposito, aunque πρός suele enfatizar la orientacion interpersonal de la intencion.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75709, 'spa', 'proximidad: ante, junto a', 'Proximidad estatica: ''ante,'' ''junto a,'' ''al lado de,'' sin implicar movimiento. Mt 3:10 (''el hacha ya esta puesta a la raiz''), Lc 10:39 (Maria sentada ''a los pies del Senor''). Las 18 apariciones suelen marcar una escena de presencia o disposicion, frecuentemente con una persona situada en un lugar significativo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75712, 'spa', 'asociacion: con', 'Asociacion o acompanamiento: ''con,'' ''en presencia de,'' ''cara a cara con.'' Este es el sentido teologicamente pregnante de Jn 1:1 (''el Verbo estaba con Dios''). Mt 26:18 (''celebrare la Pascua en tu casa / contigo''). Las 39 apariciones revelan que πρός transmite no mera cercania espacial sino relacion orientada y reciproca.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75715, 'spa', 'distributivo: entre', 'Sentido distributivo o relacional dentro de un grupo: ''entre,'' ''entre si.'' Lc 20:5 (''discutian entre si''), Lc 22:23 (''comenzaron a discutir entre ellos''). Las 8 apariciones muestran a πρός marcando deliberacion intragrupal o relacion mutua, funcion en la que se solapa con ἐν y el pronombre reciproco ἀλλήλους.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75722, 'spa', 'conformidad: conforme a', 'Conformidad o correspondencia con una norma: ''conforme a,'' ''segun,'' ''en proporcion a.'' Lc 12:47 (''sera azotado con muchos golpes conforme a su conocimiento'') y 2 Cor 5:10 (''segun lo que haya hecho''). Las 2 apariciones se situan en contextos juridicos o de juicio donde las acciones se evaluan con respecto a un estandar.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75724, 'spa', 'oposicion: contra', 'Orientacion adversativa u hostil: ''contra.'' Mt 4:6 (''para que no tropieces tu pie contra una piedra''), Mc 12:12 (''sabian que habia dicho la parabola contra ellos''). Solo 3 apariciones con sentido claramente adversativo, lo que sugiere que el Nuevo Testamento prefiere κατά para la oposicion, reservando πρός para casos de confrontacion directa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75725, 'spa', 'causal: por causa de', 'Sentido causal: ''por causa de,'' ''a causa de.'' Mt 19:8 (''por la dureza de vuestro corazon Moises os permitio'') y Mc 10:5 (pasaje paralelo). Solo 2 apariciones, ambas en la misma tradicion sinoptica sobre el divorcio, donde πρός con acusativo explica el motivo o razon detras de una concesion legal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75732, 'spa', 'Acercar o presentar', 'Traer cerca, conducir hacia, presentar ante alguien, abarcando desde la presentación física hasta el acceso teológico. Lucas 9:41 es una orden directa de traer al muchacho afligido. Hechos 16:20 describe a Pablo y Silas arrastrados ante las autoridades, y Hechos 27:27 emplea el sentido náutico de tierra que «se acerca». El uso culminante es 1 Pedro 3:18, donde la muerte de Cristo es el medio para «llevarnos a Dios».');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75733, 'spa', 'Acceso espiritual', 'Describe el acceso espiritual que los creyentes tienen a Dios por medio de Cristo. Romanos 5:2 declara que por Cristo hemos obtenido acceso por la fe a la gracia en la cual estamos firmes. Efesios 2:18 afirma que por medio de el ambos tenemos acceso en un mismo Espiritu al Padre. Efesios 3:12 anade que en Cristo tenemos confianza y acceso con seguridad mediante la fe en el.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75734, 'spa', 'Persona que mendiga', 'Identifica a personas que viven de la mendicidad. Marcos 10:46 presenta a Bartimeo, un mendigo ciego, hijo de Timeo. Juan 9:8 se refiere dos veces al hombre nacido ciego: los vecinos preguntaban si no era aquel que se sentaba a mendigar. El texto griego contiene tanto un sustantivo como un participio, ambos enfatizando su condicion de mendigo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75742, 'spa', 'Esperar con anticipación y esperanza algo futuro, ya sea un evento, una persona ', 'Esperar con anticipación y esperanza algo futuro, ya sea un evento, una persona o una promesa divina. Simeón esperaba la consolación de Israel (Lc 2:25), Ana hablaba a todos los que aguardaban la redención de Jerusalén (Lc 2:38), y José de Arimatea esperaba el reino de Dios (Mr 15:43; Lc 23:51). En Lc 12:36 los siervos esperan el regreso de su señor.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75745, 'spa', 'Recibir o acoger a alguien o algo con favor, hospitalidad o aprobación moral', 'Recibir o acoger a alguien o algo con favor, hospitalidad o aprobación moral. En Lc 15:2 los fariseos murmuran que Jesús ''recibe a los pecadores y come con ellos''. Pablo insta a la iglesia de Roma a recibir a Febe ''de manera digna de los santos'' (Ro 16:2) y a acoger a Epafrodito con gozo (Fil 2:29). He 11:35 amplía el sentido hacia la aceptación de promesas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75755, 'spa', 'Esperar, aguardar o estar atento a alguien o algo con anticipación paciente, a m', 'Esperar, aguardar o estar atento a alguien o algo con anticipación paciente, a menudo corporal. La espera es típicamente esperanzada o ansiosa, e implica presencia física y orientación hacia la persona o evento esperado. La congregación de Zacarías ''lo esperaba'' y se asombraba de su tardanza (Lc 1:21); las multitudes ''esperaban expectantes'' respecto al Mesías (Lc 3:15); Juan el Bautista envía a preguntar si Jesús es ''el que había de venir'' (Mt 11:3; Lc 7:19-20).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75757, 'spa', 'Prever o anticipar algo mentalmente, enfocándose en el estado cognitivo de supos', 'Prever o anticipar algo mentalmente, enfocándose en el estado cognitivo de suposición más que en la postura física de espera. El énfasis recae en lo que la mente proyecta, no en lo que hace el cuerpo. En Mt 24:50 y Lc 12:46, el señor llega el día que el siervo ''no espera'' -- el punto es el fallo del cálculo mental, no la ausencia de vigilia física. Los malteses ''esperaban'' que Pablo se hinchara o cayera muerto (Hch 28:6), una suposición mental basada en sus creencias sobre el veneno de serpiente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75770, 'spa', 'acercarse físicamente', 'La gran mayoría de las ocurrencias (unas 77) describen acercamiento físico: venir hacia, aproximarse o dirigirse a alguien en el espacio narrativo. Mateo lo emplea como fórmula introductoria habitual: ''y habiéndose acercado (προσελθών), él/ellos dijeron...'' (Mat 4:11; 8:2, 5, 19). Abarca desde la aproximación reverente del leproso hasta el arresto en Getsemaní.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75774, 'spa', 'acercarse a Dios en adoración', 'Unas 7 ocurrencias pasan al registro cultual o espiritual: acercarse a Dios en adoración, oración o fe. Este sentido se concentra en Hebreos, donde el autor exhorta a los creyentes a ''acercarnos con confianza al trono de la gracia'' (Heb 4:16) y a ''acercarnos con corazón sincero'' (Heb 10:22; 11:6). El eco del acercamiento sacerdotal veterotestamentario (hebreo קרב) es inconfundible.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75784, 'spa', 'ir a visitar con propósito', 'Dos ocurrencias (Hch 9:1; 10:28) enfatizan el dirigirse a alguien con un propósito específico o encargo, donde el matiz direccional es ''ir hacia'' más que ''venir hacia'' el narrador. En Hechos 9:1, Saulo ''fue al'' sumo sacerdote para obtener cartas; en Hechos 10:28, Pedro explica la impropiedad de ''visitar'' a un gentil.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75793, 'spa', 'oración, acto de orar', 'oración, acto de orar');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75800, 'spa', 'orar a Dios', 'Elevar oración, súplica o adoración dirigida a Dios, abarcando petición, intercesión, acción de gracias y comunión devocional. Se usa tanto de la vida de oración de Jesús (Mat 14:23; Mc 1:35; Lc 6:12) como de su enseñanza sobre la oración (Mat 6:5-9), así como de la oración apostólica y congregacional en Hechos y las Epístolas. La voz media (προσεύχομαι) transmite compromiso personal: uno se dirige a Dios directamente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75825, 'spa', 'Guardarse, cuidarse o estar en guardia contra el peligro o el engaño', 'Guardarse, cuidarse o estar en guardia contra el peligro o el engaño. Jesús domina este grupo semántico: ''guardaos de los falsos profetas'' (Mat 7:15), ''guardaos de la levadura de los fariseos'' (Mat 16:6, 11-12; Mar 8:15; Luc 12:1), ''guardaos de los hombres'' que perseguirán (Mat 10:17), y ''guardaos de los escribas'' (Luc 20:46). La construcción típica usa προσέχετε + ἀπό (''apartaos de'').');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75826, 'spa', 'Prestar atención, poner cuidado o dirigir la mente con atención hacia una person', 'Prestar atención, poner cuidado o dirigir la mente con atención hacia una persona, enseñanza o mensaje. Los samaritanos ''prestaban atención'' a la hechicería de Simón y luego al evangelio de Felipe (Hch 8:6, 10-11), los líderes judíos son advertidos a ''considerar cuidadosamente'' lo que hacen con los apóstoles (Hch 5:35), y Pablo dice a Timoteo que ''preste atención a la lectura, la exhortación y la enseñanza'' (1 Tim 4:1, 13).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75835, 'spa', 'Dedicarse a o ocuparse de una práctica o deber a lo largo del tiempo', 'Dedicarse a o ocuparse de una práctica o deber a lo largo del tiempo. Hebreos 7:13 dice que aquel de quien se hablan estas cosas ''se ha dedicado'' (προσέσχηκεν) al altar, es decir, ha servido en el servicio sacerdotal o se ha consagrado a él. Se trata de una orientación sostenida y habitual, no de un acto momentáneo de atención ni de una advertencia puntual.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75837, 'spa', 'Converso al judaísmo', 'Gentil convertido al judaísmo que ha abrazado plenamente la fe judía, incluyendo la circuncisión (para los varones), la observancia de la Torá y la participación en el culto del templo. Las traducciones en múltiples idiomas retienen de manera consistente el préstamo transliterado («prosélito»), subrayando que se trata de una categoría fija y no de una descripción vaga. Jesús advierte sobre un proselitismo agresivo que produce hijos del infierno (Mt 23:15).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75838, 'spa', 'Transitorio y efímero', 'Que dura solo por una temporada limitada; transitorio e impermanente, contrastado típicamente con lo que es eterno (αἰώνιος). En las parábolas sinópticas describe la fe superficial que se desmorona ante la tribulación porque no tiene raíz (Mt 13:21; Mr 4:17). El uso paulino en 2 Corintios 4:18 establece el contraste fundamental del Nuevo Testamento: lo visible es temporal, lo invisible es eterno.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75839, 'spa', 'Llamar o convocar a alguien hacia sí, consistentemente en voz media, expresando ', 'Llamar o convocar a alguien hacia sí, consistentemente en voz media, expresando autoridad e iniciativa personal. Jesús lo usa para comisionar a los Doce (Mat 10:1), reunir multitudes para enseñanzas cruciales (Mar 7:14, Mat 15:10), y señalar a individuos (Mat 18:2). En Hechos, el Espíritu Santo emplea el mismo verbo para apartar a Bernabé y Saulo para la misión (Hch 13:2), extendiendo el patrón de llamamiento divino con autoridad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75846, 'spa', 'Persistir en, dedicarse a', 'Persistir en, dedicarse a. Persistir firmemente o entregarse de todo corazón a una actividad, especialmente la oración, la enseñanza o el ministerio. Este es el sentido característico en Hechos: los 120 ''perseveraban en la oración'' (Hch 1:14), la iglesia se dedicaba a la enseñanza apostólica y la comunión (Hch 2:42), y los apóstoles resolvieron ''dedicarse de continuo a la oración y al ministerio de la palabra'' (Hch 6:4).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75848, 'spa', 'Atender, servir a', 'Atender, servir a. Atender constantemente a una persona, estar a su disposición — una persistencia relacional más que centrada en una actividad. En Marcos 3:9 Jesús dice a sus discípulos que tengan una barca ''dispuesta'' (προσκαρτερῇ) para él a causa de la multitud, y en Hechos 10:7 uno de los soldados de Cornelio que ''le servía constantemente'' es enviado a Jope.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75858, 'spa', 'Tropiezo u obstáculo', 'Un tropiezo u obstáculo que provoca que alguien caiga, usado metafóricamente en el NT para cualquier cosa que cause ofensa espiritual o conduzca a otro al pecado. Cristo mismo es llamado ''la piedra de tropiezo'' para el Israel incrédulo (Rom 9:32-33, basado en Isa 8:14 e Isa 28:16), mientras que Pablo insta a los creyentes a no poner un proskomma ante un hermano más débil (Rom 14:13, 20; 1 Cor 8:9).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75862, 'spa', 'Tropezar (espiritual)', 'Tropezar u ofenderse en sentido metafórico o espiritual, indicando la incapacidad de aceptar la verdad, la caída en pecado o el encuentro con un obstáculo en el camino de la fe. Es el uso predominante en el Nuevo Testamento. En Juan 11:9-10 Jesús contrasta caminar de día y de noche para distinguir a quienes tropiezan espiritualmente. Romanos 9:32 describe a Israel tropezando con la piedra de tropiezo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75863, 'spa', 'Golpearse contra (físico)', 'Golpear una cosa contra otra en sentido literal y físico: el pie contra una piedra, o las aguas contra una casa. En Mateo 4:6 y Lucas 4:11, el diablo cita el Salmo 91:12 prometiendo protección angélica ''para que no tropieces con tu pie en piedra'', y en Mateo 7:27 las lluvias y los vientos ''golpearon'' la casa edificada sobre la arena.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75868, 'spa', 'postrarse en homenaje', 'Postrarse en homenaje respetuoso o súplica ante una persona de autoridad o grandeza percibida, sin implicar necesariamente adoración divina plena. Incluye a los magos ante el niño Jesús (Mat 2:11), el leproso que se arrodilla ante Jesús pidiendo sanidad (Mat 8:2) y Jairo que cae a los pies de Jesús (Mat 9:18). Existe una tensión interesante: el español a menudo usa adorar incluso aquí, difuminando la frontera con el sentido plenamente cultual.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75869, 'spa', 'adorar a Dios', 'Adoración religiosa plena dirigida a Dios, un ser divino o un objeto de devoción, expresando veneración y reverencia. Incluye la adoración al Dios verdadero (Jn 4:23-24; Ap 4:10), la adoración idolátrica (Mat 4:9; Ap 13:4) y la negativa angélica a recibir adoración (Ap 19:10; 22:9). El español adorar, el francés adorer y el alemán anbeten convergen en el sentido devocional y religioso.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75895, 'spa', 'Recibir, acoger o aceptar a una persona en comunión o comunidad, el núcleo relac', 'Recibir, acoger o aceptar a una persona en comunión o comunidad, el núcleo relacional y teológico del término. Pablo insta a la iglesia de Roma a ''recibir'' al débil en la fe (Ro 14:1) y declara que ''Cristo nos recibió'' (Ro 15:7). Los malteses acogieron con inusual bondad a la compañía de Pablo tras el naufragio (Hch 28:2).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75896, 'spa', 'Tomar a alguien aparte en privado, a menudo para corrección, instrucción o conve', 'Tomar a alguien aparte en privado, a menudo para corrección, instrucción o conversación íntima. Pedro ''tomó aparte a Jesús'' y comenzó a reprenderlo (Mt 16:22; Mr 8:32), y Priscila y Aquila ''tomaron aparte a Apolos'' para explicarle el Camino con más exactitud (Hch 18:26). El gesto físico de apartar a alguien del grupo es vívido.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75899, 'spa', 'Tomar algo para sí, especialmente alimento, o reclutar personas para un propósit', 'Tomar algo para sí, especialmente alimento, o reclutar personas para un propósito. Durante la tormenta, Pablo instó a todos a bordo a ''tomar alimento'' (Hch 27:33), y comieron (Hch 27:36). En Hch 17:5, ciertos hombres ''tomaron consigo'' a algunos malvados del mercado. El sentido es instrumental y adquisitivo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75905, 'spa', 'Permanecer, continuar con', 'Permanecer con, quedarse, continuar — denota presencia persistente junto a una persona, en un lugar o en un estado de compromiso. En los relatos de la multiplicación, las multitudes han «permanecido con» Jesús durante días (Mt 15:32; Mr 8:2), expresando resistencia física junto con devoción. En Hechos se desplaza hacia la perseverancia fiel: Bernabé exhorta a los nuevos creyentes a «permanecer con el Señor» con devoción sincera (Hch 11:23).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75916, 'spa', 'Postrarse en reverencia', 'Caer ante alguien como acto de súplica, reverencia o adoración, el sentido predominante en el Nuevo Testamento. Las personas se postran ante Jesús movidas por desesperación, asombro o reconocimiento de su autoridad divina. Marcos 5:33 muestra a la mujer sanada cayendo con temor y contando toda la verdad; Marcos 7:25 presenta a una madre a los pies de Jesús rogando por su hija endemoniada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75919, 'spa', 'Caer sobre, golpear', 'Caer sobre algo o golpear contra ello con fuerza física impersonal, dicho de elementos naturales que impactan una estructura. El único caso aparece en Mateo 7:25, donde la lluvia, las aguas y los vientos ''cayeron sobre'' la casa edificada sobre la roca. Aquí el sujeto ya no es una persona que se acerca reverentemente, sino fuerzas naturales que arremeten con violencia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75924, 'spa', 'Mandar, ordenar', 'Emitir un mandato o directiva autoritativa que exige cumplimiento, dicho de órdenes dadas por Dios, Jesús, Moisés o intermediarios angélicos. En Mt 1:24 José hace lo que el ángel del Señor le «mandó»; en Mt 8:4, Mr 1:44 y Lc 5:14 Jesús dice al leproso sanado que ofrezca lo que Moisés «mandó»; y en Hch 10:33 Cornelio reúne a su casa por lo que Dios «ordenó» mediante un ángel.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75925, 'spa', 'Designar, señalar', 'Designar, señalar o disponer de antemano, implicando preordenación divina o disposición soberana más que una directiva verbal específica. En Hch 17:26 Pablo declara que Dios «señaló» (προστάξας) los tiempos y los límites de la habitación de las naciones. El español «señalados» («designados, marcados») capta este sentido como distinto de «mandó» («ordenó»), revelando el desplazamiento de mandato verbal a ordenamiento cósmico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75928, 'spa', 'Añadir algo a una cantidad, grupo o entidad existente, o aumentar y conceder alg', 'Añadir algo a una cantidad, grupo o entidad existente, o aumentar y conceder algo más. Este sentido cubre la gran mayoría de los usos neotestamentarios: Dios añade creyentes a la iglesia (Hch 2:41, 47; 5:14; 11:24), Jesús promete que todas las necesidades serán añadidas a quienes buscan el reino (Mt 6:33; Lc 12:31), y diversas parábolas y exhortaciones emplean el verbo para indicar adición o incremento.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75933, 'spa', 'Hebraísmo que significa proceder, continuar o hacer algo más, reflejando la cons', 'Hebraísmo que significa proceder, continuar o hacer algo más, reflejando la construcción hebrea con יָסַף donde el verbo señala continuación o repetición en lugar de adición literal. En Hechos 12:3, Lucas escribe que Herodes ''procedió a arrestar también a Pedro,'' una construcción septuagintista donde προστίθημι funciona como verbo auxiliar que modifica la acción principal, indicando que se repite o se extiende.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75941, 'spa', 'Correr hacia alguien', 'Describe el acto de correr hacia Jesus con urgencia o entusiasmo. Marcos 9:15 relata que la multitud, al ver a Jesus, corrio hacia el y le saludo. Marcos 10:17 presenta al joven rico que corrio hacia Jesus y se arrodillo ante el. Hechos 8:30 describe a Felipe, quien corrio hacia el carro del etiope y le oyo leer al profeta Isaias.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75945, 'spa', 'traer, presentar', 'traer, presentar');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75946, 'spa', 'ofrecer un sacrificio o don', 'ofrecer un sacrificio o don');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75953, 'spa', 'tratar, lidiar con', 'tratar, lidiar con');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75974, 'spa', 'Ofrenda, sacrificio', 'Ofrenda o sacrificio religioso presentado a Dios, que abarca tanto el acto de traer una ofrenda como la ofrenda misma. En el Nuevo Testamento va desde la descripción paulina de los conversos gentiles como una ''ofrenda'' aceptable (Ro 15:16) hasta las ofrendas rituales vinculadas a votos en el templo (Hch 21:26; 24:17), y culmina en el autosacrificio de Cristo que hace obsoletos todos los demás sacrificios (Ef 5:2; Heb 10:5, 10, 14, 18).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75978, 'spa', 'Llamar, dirigirse a', 'Llamar o dirigirse a alguien de forma directa, ya sea para convocarlo, saludarlo o entregarle un mensaje cara a cara. Las traducciones multilingües convergen en el habla dirigida: el alemán ''spricht an'' (interpelar), el francés ''adresser la parole'' (dirigir la palabra). En los Evangelios, el verbo aparece tanto cuando niños llaman a sus compañeros en el ágora (Mt 11:16; Lc 7:32) como cuando Jesús nombra a sus discípulos (Lc 6:13).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75987, 'spa', 'Parcialidad injusta', 'El acto de juzgar o tratar a las personas de manera diferente según indicadores externos como riqueza, rango social u origen étnico, en lugar de por su carácter o mérito. La etimología literal, «recibir el rostro», hace eco del modismo hebreo נָשָׂא פָנִים, que la LXX traduce con este grupo de palabras. Pablo, escribiendo a Roma, insiste en que Dios no ejerce tal sesgo en su juicio (Ro 2:11); el mismo principio rige la relación entre amos y siervos (Ef 6:9; Col 3:25).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75988, 'spa', 'rostro, semblante', 'El rostro o semblante físico y, por modismo semítico (reflejando el hebreo panim), la presencia, el frente o la superficie de algo. Todas las traducciones principales usan un vocablo de rostro/semblante: español rostro, alemán Angesicht, francés visage, confirmando el rango de lo concreto a lo espacial. En Mat 17:2, el rostro de Jesús resplandece en la Transfiguración; en Hch 3:20, designa la presencia de Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75992, 'spa', 'persona, apariencia externa', 'Por metonimia, la persona externa, la apariencia o la posición social: el rostro representando al individuo entero. El español traduce personas y el francés personnes, distinguiendo este sentido del de rostro literal. Pablo perdona ''en la persona (πρόσωπον) de Cristo'' (2 Co 2:10), y Judas 1:16 advierte contra quienes hacen acepción de personas (πρόσωπα).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (75996, 'spa', 'Anterior / anteriormente / antes', 'Anterior / anteriormente / antes. Adjetivo o adverbio comparativo que indica prioridad temporal — lo que vino antes en el tiempo, traducido como ''anterior, anteriormente, antes, en primer lugar''. Se aplica adverbialmente para describir acciones previas (Jn 7:50, Nicodemo viniendo ''anteriormente''; Jn 9:8, el ciego visto ''antes''; Gá 4:13, la visita anterior de Pablo) y adjetivalmente para caracterizar un estado previo (Ef 4:22, la ''antigua manera de vivir''; 1 Ti 1:13, la vida anterior de Pablo).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76001, 'spa', 'Proposito deliberado', 'Describe la intencion deliberada o la predeterminacion divina. Romanos 1:13 expresa la intencion de Pablo: muchas veces me he propuesto ir a vosotros. Romanos 3:25 declara que Dios puso a Cristo como propiciacion por medio de la fe en su sangre. Efesios 1:9 habla de Dios dandonos a conocer el misterio de su voluntad segun su proposito que se propuso en Cristo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76005, 'spa', 'Pretexto, apariencia falsa', 'Una razón fabricada o insincera que se da para ocultar el verdadero motivo: una fachada o pretexto. La evidencia multilingüe es notablemente uniforme: español ''pretexto'', francés ''prétexte'', alemán ''Vorwand'' y hindi ''bahane se'' apuntan todos al engaño deliberado. La triple denuncia de Jesús contra la oración hipócrita (Mt 23:14; Mr 12:40; Lc 20:47) ancla este sentido, mientras Pablo reconoce en Fil 1:18 que algunos predican a Cristo ''con pretexto''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76007, 'spa', 'Excusa, justificación', 'Una razón o justificación ofrecida en defensa propia, una excusa que puede o no ser legítima. En Juan 15:22, Jesús declara que el mundo ya no tiene πρόφασις para su pecado: la palabra funciona no como camuflaje engañoso, sino como un alegato defensivo que el acusado podría invocar. Las traducciones francesa y alemana (''prétexte'', ''Vorwand'') difuminan esta distinción, pero el contexto deja claro que lo ausente es una defensa genuina, no una coartada falsa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76009, 'spa', 'El don del habla capacitada por el Espíritu, el acto de entregar un mensaje divi', 'El don del habla capacitada por el Espíritu, el acto de entregar un mensaje divino, o el mensaje mismo. En 1 Corintios 12-14, Pablo la trata como un carisma que edifica a la iglesia, superior a las lenguas porque comunica de manera inteligible. En Mateo 13:14, Jesús cita la προφητεία de Isaías como predicción cumplida. Las epístolas pastorales (1 Ti 1:18; 4:14) recuerdan palabras proféticas pronunciadas sobre Timoteo en su ordenación. En Apocalipsis, el término enmarca todo el libro como revelación profética.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76012, 'spa', 'Hablar o declarar por inspiración divina, abarcando tanto la predicción de event', 'Hablar o declarar por inspiración divina, abarcando tanto la predicción de eventos futuros como la proclamación autoritativa del mensaje de Dios. En los Evangelios, los adversarios de Jesús le exigen burlonamente que profetice (Mat 26:68; Luc 22:64), mientras Jesús mismo cita a profetas que hablaron por el Espíritu (Mat 15:7). En las cartas de Pablo, el verbo designa un don espiritual ejercido en la adoración comunitaria para la edificación (1 Cor 14:1-5).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76027, 'spa', 'profeta, portavoz de Dios', 'Persona que habla en nombre de Dios, transmitiendo revelación, advertencia o promesa divina. En el Nuevo Testamento abarca a los profetas veterotestamentarios citados en las Escrituras (Mt 1:22; 2:5), a Jesús reconocido como profeta por las multitudes (Mt 21:11; Lc 24:19) y a los profetas dotados por el Espíritu en las comunidades cristianas primitivas (1 Co 14:29; Ef 4:11). La idea subyacente es siempre la de portavoz autorizado de lo divino.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76039, 'spa', 'Designación divina previa', 'Describe la designación o elección divina para propósitos específicos. En Hechos 3:20 se habla de Jesús como aquel a quien Dios designó de antemano. Hechos 22:14 registra a Ananías diciendo a Pablo que el Dios de sus padres lo designó para conocer su voluntad. Hechos 26:16 presenta a Jesús apareciendo a Pablo para designarlo como ministro y testigo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76042, 'spa', 'Popa del barco', 'Se refiere a la popa de un barco en narraciones marítimas. Marcos 4:38 describe a Jesús durante la tempestad durmiendo en la popa sobre un cabezal. Hechos 27:29 relata cómo los marineros echaron cuatro anclas desde la popa por temor a encallar. Hechos 27:41 describe el naufragio cuando la popa se deshacía por la violencia de las olas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76043, 'spa', 'Adverbio temporal que señala las primeras horas de la mañana, generalmente alred', 'Adverbio temporal que señala las primeras horas de la mañana, generalmente alrededor del amanecer. Enmarca eventos clave: la oración de Jesús antes del alba (Mr 1:35), las mujeres en el sepulcro vacío (Mr 16:2; Jn 20:1), la enseñanza en el templo (Jn 8:2) y la contratación de obreros para la viña (Mt 20:1). Un solo sentido temporal uniforme.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76054, 'spa', 'Asiento de honor', 'El asiento principal o más prestigioso en una sinagoga o asamblea pública, reservado para personas de alta posición religiosa o social. La evidencia arqueológica confirma que las sinagogas antiguas disponían de un banco de piedra frente a la congregación, asignado a los ancianos y maestros distinguidos. Jesús critica a los escribas y fariseos por codiciar estas posiciones como símbolos de estatus (Mt 23:6; Lc 20:46).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76055, 'spa', 'Primer puesto en banquete', 'El asiento principal o lugar de honor en un banquete: la posición más prestigiosa para reclinarse. En el triclinio antiguo, ciertas posiciones conferían mayor estatus, y esta palabra designa la más codiciada. Jesús la emplea como diagnóstico del orgullo religioso: los escribas y fariseos «aman los primeros asientos» (Mat 23:6; Mar 12:39; Luc 20:46).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76056, 'spa', 'primero', 'Adverbio de prioridad temporal o lógica que significa ''primero, antes que nada''. El español primero, el francés premièrement y el alemán zuerst captan la fuerza secuencial. En la enseñanza de Jesús, introduce frecuentemente un requisito previo imperativo (Mat 5:24; 7:5; 12:29). Pablo lo emplea para ordenar las etapas del plan redentor de Dios (Ro 1:16; 2:9-10). Presupone una secuencia y destaca lo que debe cumplirse antes de avanzar.');